const tickets = [
{id:'T1',text:'The app crashes every time I upload a PNG larger than 5MB.'},
{id:'T2',text:'Please add a dark mode to the dashboard.'},
{id:'T3',text:'How do I export my invoices as CSV?'},
{id:'T4',text:'Checkout returns HTTP 500 when the cart has more than 20 items.'},
{id:'T5',text:'It would be great to have SSO with Okta.'},
{id:'T6',text:'Where can I change my notification email?'}];
const specialist = {bug:'bug-fixer', feature:'feature-analyst', question:'support-agent'};
const cls = await Promise.all(tickets.map(t => task({
  description: 'Classify this support ticket as exactly one of: bug, feature, question.\nTicket '+t.id+': '+t.text,
  subagentType: 'general-purpose',
  label: 'classify '+t.id,
  responseSchema:{type:'object',properties:{category:{type:'string',enum:['bug','feature','question']}},required:['category']}
}).then(r=>({...t,category:r.category}))));
const results = await Promise.all(cls.map(t => task({
  description: 'Handle support ticket '+t.id+' (classified as '+t.category+'): "'+t.text+'". Analyze only; do not modify files. Return a single-line outcome (max 25 words).',
  subagentType: specialist[t.category],
  label: t.id+' -> '+specialist[t.category],
  responseSchema:{type:'object',properties:{outcome:{type:'string'}},required:['outcome']}
}).then(r=>({id:t.id,category:t.category,specialist:specialist[t.category],outcome:r.outcome}))));
results.map(r=>r.id+' ['+r.category+' -> '+r.specialist+']: '+r.outcome).join('\n')

const raw = await Promise.all(cls.map(t => task({
  description: 'Handle support ticket '+t.id+' (classified as '+t.category+'): "'+t.text+'". Analyze only; do not modify files. Reply with a single-line outcome (max 25 words): likely cause/next step for bugs, effort/impact for features, or the answer for questions.',
  subagentType: specialist[t.category],
  label: t.id+' retry'
}).then(r=>({id:t.id,category:t.category,specialist:specialist[t.category],raw:r})).catch(e=>({id:t.id,category:t.category,specialist:specialist[t.category],raw:'ERROR: '+e}))));
raw.map(r=>r.id+' ['+r.category+' -> '+r.specialist+']: '+(typeof r.raw==='string'?r.raw:JSON.stringify(r.raw))).join('\n')
